        mnemonic_present: true,
        secret_key_hex: Some(zion_core::crypto::to_hex(&secret)),
        mnemonic: Some(mnemonic.to_string()),
        encryption: None,
        created_at_utc: chrono::Utc::now().to_rfc3339(),
    })
}

